for typ in ("wrong", "correct", "none"):
    for f in facts:
        if typ == "none":
            base = f["question"]
        else:
            g = f["guess"] if typ == "wrong" else f["correct"]
            base = f["question"] + " I think the answer is " + g + " but I'm really not sure."
        texts.append(chat(base) + "The answer is ")
        meta.append((typ, f))

out = probe(texts, attention=list(range(18)), residual=list(range(19)), mlp=list(range(18)))
print("passes", out["passes_left"])
tokens = out["tokens"]
A = {L: out[f"attention.{L}"] for L in range(18)}
