M = {L: out[f"mlp.{L}"] for L in range(18)}
T = A[0].shape[-1]
print("T", T, "n", len(tokens))

# parse guess spans for wrong/correct prompts by token strings
wspans=[]; cspans=[]
for i,(typ,f) in enumerate(meta):
    t = tokens[i]
    dec = [tokenizer.decode([int(x)]) for x in t]
    span=None
    # find ' answer' then ' is', take after until ' but'
    try:
        ja = max(j for j,s in enumerate(dec) if s==" answer")
        ji = next(j for j in range(ja+1, len(dec)) if dec[j]==" is")
        jb = next(j for j in range(ji+1, len(dec)) if dec[j]==" but")
        span = list(range(ji+1, jb))
    except Exception as e:
        span = []
    if typ=="wrong": wspans.append(span)
    if typ=="correct": cspans.append(span)

def agg(L, spans):
    # mean over facts of attention mass on span, per head
    res=np.zeros((50,4))
    for i,sp in enumerate(spans):
        t = tokens[i]
        if sp:
            res[i] = A[L][i,:,:len(t)][:,sp].sum(axis=1)
    return res

print("Attention mass to guess span (mean over facts), by layer/head")
for L in range(18):
    aw=agg(L,wspans).mean(axis=0)
    ac=agg(L,cspans).mean(axis=0)
    print(L, "wrong", np.round(aw,4), "correct", np.round(ac,4))

